import{_ as d,a0 as a,w as l,s,ao as p,I as n,x as t,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/13 - The history of Android","title":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端","tag":"The history of Android","desc":""},"relativePath":"The history of Android/13 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/13 - The history of Android.md"};function m(T,o,f,g,h,A){const e=a("Link");return l(),s("div",null,[o[25]||(o[25]=p('<h1 id="安卓編年史-13-android-2-1-update-1——無盡戰爭的開端" tabindex="-1">安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 <a class="header-anchor" href="#安卓編年史-13-android-2-1-update-1——無盡戰爭的開端" aria-label="Permalink to “安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/ready-fight.png" alt=""></p><h3 id="android-2-1-update-1——無盡戰爭的開端" tabindex="-1">Android 2.1, update 1——無盡戰爭的開端 <a class="header-anchor" href="#android-2-1-update-1——無盡戰爭的開端" aria-label="Permalink to “Android 2.1, update 1——無盡戰爭的開端”">​</a></h3>',3)),n("p",null,[o[1]||(o[1]=t("谷歌是第一代 iPhone 的主要合作伙伴——公司為蘋果的移動操作系統提供了谷歌地圖、搜索，以及 Youtube。在那時，谷歌 CEO 埃裏克·施密特是蘋果的董事會成員之一。實際上，在最初的蘋果發佈會上，施密特是在史蒂夫·喬布斯",-1)),r(e,{href:"http://www.youtube.com/watch?v=9hUIxyE2Ns8#t=3016"},{default:i(()=>[...o[0]||(o[0]=[t("之後第一個登台的人",-1)])]),_:1}),o[2]||(o[2]=t("，他還開玩笑説兩家公司如此接近，都可以合併成“AppleGoo”了。",-1))]),o[26]||(o[26]=n("p",null,"當谷歌開發安卓的時候，兩家公司間的關係慢慢變得充滿爭吵。然而，谷歌很大程度上還是通過拒 iPhone 關鍵特性於安卓門外，如雙指縮放，來取悦蘋果。儘管如此，Nexus One 是第一部不帶鍵盤的直板安卓旗艦機，設備被賦予了和iPhone 相同的外觀因素。Nexus One 結合了新軟件和谷歌的品牌，這是壓倒蘋果的最後一根稻草。根據沃爾特·艾薩克森為史蒂夫·喬布斯寫的傳記，2010 年 1 月在看到了 Nexus One 之後，這位蘋果的 CEO 震怒了，説道：“如果需要的話我會用盡最後一口氣，以及花光蘋果在銀行裏的 400 億美元，來糾正這個錯誤……我要摧毀安卓，因為它完全是偷竊來的產品。我願意為此發起核戰爭。”",-1)),n("p",null,[o[4]||(o[4]=t("所有的這些都在秘密地發生，僅在 Nexus One 發佈後的幾年後才公諸於眾。公眾們最早在安卓 2.1——推送給 Nexus One 的一個稱作 “",-1)),r(e,{href:"http://arstechnica.com/gadgets/2010/02/googles-nexus-one-gets-multitouch/"},{default:i(()=>[...o[3]||(o[3]=[t("2.1 update 1",-1)])]),_:1}),o[5]||(o[5]=t("” 的更新，發佈後一個月左右捕捉到谷歌和蘋果間愈演愈烈的分歧氣息。這個更新添加了一個功能，正是 iOS 一直居於安卓之上的功能：雙指縮放。",-1))]),o[27]||(o[27]=n("p",null,"儘管安卓從 2.0 版本開始就支持多點觸控 API 了，但系統的默認應用在喬布斯的命令下依然和這項實用的功能劃清界限。在關於 Nexus One 的和解會議談崩了之後，谷歌再也沒有理由拒雙指縮放於安卓門外了。谷歌給設備推送了更新，安卓終於補上了不足之處。",-1)),o[28]||(o[28]=n("p",null,"隨着谷歌地圖、瀏覽器以及相冊中雙指縮放的全面啓用，谷歌和蘋果的智能手機戰爭也就此拉開序幕。在接下來的幾年中，兩家公司會變成死敵。雙指縮放功能更新的一個月後，蘋果開始了它的征途，起訴了所有使用安卓的公司。HTC、摩托羅拉以及三星都被告上法庭，直到現在都還有一些訴訟還沒解決。施密特也辭去了蘋果董事會的職務。谷歌地圖和 Youtube 被從 iPhone 中移除，蘋果甚至開始打造自己的地圖服務。今天，這兩位選手幾乎是 “AppleGoo” 競賽的唯一選手，涉及領域十分廣泛：智能手機、平板、筆記本、電影、TV 秀、音樂、書籍、應用、郵件、生產力工具、瀏覽器、個人助理、雲存儲、移動廣告、即時通訊、地圖以及機頂盒……以及不久它們將會在汽車智能、穿戴設備、移動支付，以及客廳娛樂等進行競爭。",-1)),o[29]||(o[29]=n("h3",{id:"android-2-2-froyo——更快更華麗",tabindex:"-1"},[t("Android 2.2 Froyo——更快更華麗 "),n("a",{class:"header-anchor",href:"#android-2-2-froyo——更快更華麗","aria-label":"Permalink to “Android 2.2 Froyo——更快更華麗”"},"​")],-1)),n("p",null,[r(e,{href:"http://arstechnica.com/information-technology/2010/07/android-22-froyo/"},{default:i(()=>[...o[6]||(o[6]=[t("安卓 2.2",-1)])]),_:1}),o[7]||(o[7]=t(" 在 2010 年 5 月，也就是 2.1 發佈後的四個月後亮相。Froyo（凍酸奶）的亮點主要是底層優化，只為更快的速度。Froyo 最大的改變是增加了 JIT 即時編譯。JIT 自動在運行時將 java 字節碼轉換為原生碼，這會給系統全面帶來顯著的性能改善。",-1))]),o[30]||(o[30]=n("p",null,"瀏覽器同樣得到了性能改善，這要感謝整合了來自 Chrome 的 V8 Javascript 引擎。這是安卓瀏覽器從 Chrome 借鑑的許多特性中的第一個，最終系統內置的瀏覽器會被移動版 Chrome 徹底替代掉。在那之前，安卓團隊還是需要提供一個瀏覽器。從 Chrome 借鑑特性是條升級的捷徑。",-1)),o[31]||(o[31]=n("p",null,"在谷歌專注於讓它的平台更快的同時，蘋果正在讓它的平台更全面。這位谷歌的競爭對手在一個月前發佈了 10 英寸的 iPad，先行進入了平板時代。儘管有些搭載 Froyo 和 Gingerbread 的安卓平板發佈，但谷歌的官方回應——安卓 3.0 Honeycomb（蜂巢）以及摩托羅拉 Xoom——在 9 個月後才來到。",-1)),o[32]||(o[32]=n("p",null,[n("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/02/22-2.png",alt:"Froyo底部添加了雙圖標停靠欄以及全局搜索。"})],-1)),o[33]||(o[33]=n("p",null,[n("em",null,"Froyo 底部添加了雙圖標停靠欄以及全局搜索。 [Ron Amadeo 供圖]")],-1)),o[34]||(o[34]=n("p",null,"Froyo 主屏幕最大的變化是底部的新停靠欄，電話和瀏覽器圖標填充了先前抽屜按鈕左右的空白空間。這些新圖標都是現有圖標的白色定製版本，並且用户沒辦法自己設置圖標。",-1)),o[35]||(o[35]=n("p",null,"默認佈局移除了所有圖標，屏幕上只留下一個使用提示小部件，引導你點擊啓動器圖標以訪問你的應用。谷歌搜索小部件得到了一個谷歌 logo，它同時也是個按鈕。點擊它可以打開一個搜索界面，你可以限制搜索範圍是在互聯網、應用或是聯繫人之內。",-1)),o[36]||(o[36]=n("p",null,[n("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/03/small-market-2.jpg",alt:"下載頁面有了“更新所有”按鈕，這是個 Flash 應用，一個 flash 驅動的一切皆有可能的網站，以及“移動到 SD”按鈕。 "})],-1)),n("p",null,[n("em",null,[o[9]||(o[9]=t("下載頁面有了“更新所有”按鈕，這是個 Flash 應用，一個 flash 驅動的一切皆有可能的網站，以及“移動到 SD”按鈕。 [",-1)),r(e,{href:"http://arstechnica.com/information-technology/2010/07/android-22-froyo/"},{default:i(()=>[...o[8]||(o[8]=[t("Ryan Paul",-1)])]),_:1}),o[10]||(o[10]=t(" 供圖]",-1))])]),o[37]||(o[37]=p('<p>還有一些優秀的新功能加入了 Froyo，安卓市場加入了更多的下載控制。有個新的“更新所有”按鈕固定在了下載頁面底部。谷歌還添加了自動更新特性，只要應用權限沒有改變就能夠自動安裝應用；儘管如此，自動更新默認是關閉的。</p><p>第二張圖展示了 Adobe Flash 播放器，它是 Froyo 獨有的。這個應用作為插件加入了瀏覽器，讓瀏覽器能夠有“完整的網絡”體驗。在 2010 年，這意味着網頁充滿了 Flash 導航和視頻。Flash 是安卓相比於 iPhone 最大的不同之一。史蒂夫·喬布斯展開了一場對抗 Flash 的聖戰，聲稱它是一個被淘汰的、充滿 bug 的軟件，並且蘋果不會允許它在 iOS 存在。所以安卓接納了 Flash 並且讓它在安卓上運行，給予用户在安卓上擁有接近可用的 flash 實現。</p><p>在那時，Flash 甚至能夠讓桌面電腦崩潰，所以在移動設備上一直保持打開狀態會帶來可怕的體驗。為了解決這個問題，安卓瀏覽器上的 Flash 可以設置為“按需打開”——除非用户點擊 Flash 佔位圖標，否則不會加載 Flash 內容。對 Flash 的支持將會持續到安卓 4.1，Adobe 在那時放棄並且結束了這個項目。Flash 從頭到尾從未在安卓上完美運行過。而 Flash在 iPhone 這個最流行的移動設備上的缺失，推動了互聯網最終放棄了這個平台。</p><p>最後一張圖片顯示的是新增的移動應用到 SD 卡功能，在那個手機只有 512 MB內置存儲的時代，這個功能十分的必要的。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/22carcam-2.png" alt="駕駛模式應用。相機現在可以旋轉了。"></p><p><em>駕駛模式應用。相機現在可以旋轉了。 [Ron Amadeo 供圖]</em></p><p>相機應用終於更新支持縱向模式了。相機設置被從抽屜中移出，變成一條半透明的按鈕帶，放在了快門按鈕和其他控制鍵旁邊。這個新設計看起來從 Cooliris 相冊中獲得了許多靈感，半透明的、有彈性的聊天氣泡彈出窗口。看到更現代的Cooliris 風格 UI 設計被嫁接到皮革裝飾的相機應用確實十分奇怪——從審美上來説一點都不搭。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/facebook.png" alt="半殘缺的Facebook應用是個常見的2x3導航頁面的優秀範例。谷歌Goggles被包含了進來但同樣是殘缺的。"></p><p><em>半殘缺的 Facebook 應用是個常見的 2x3 導航頁面的優秀範例。谷歌 Goggles 被包含了進來但同樣是殘缺的。 [Ron Amadeo 供圖]</em></p><p>不像在安卓 2.0 和 2.1 中包含的 Facebook 客户端，2.2 版本的仍然部分能夠工作並且可以登錄 Facebook 服務器。Facebook 應用是谷歌那時候設計指南的優秀範例，它建議應用擁有一個含有 3x2 圖標方陣的導航頁並作為應用主頁。</p><p>這是谷歌的第一個標準化嘗試，將導航元素從菜單按鈕裏移到屏幕上，以便用户找到它們。這個設計很實用，但它在打開應用和使用應用之間增加了額外的障礙。谷歌不久後會意識到當用户打開一個應用，顯示應用內容而不是中間導航頁是個更好的主意。以 Facebook 為例，打開應用直接打開信息訂閲會更合適。並且不久後應用設計將會把導航降級到二層位置——先是作為頂部的標籤之一，後來谷歌放在了“導航抽屜”，一個含有應用所有功能位置的滑出式面板。</p><p>還有個預裝到 Froyo 的應用是谷歌 Goggles，一個視覺搜索應用，它會嘗試辨別圖片上的主體。它在辨別藝術品、地標以及條形碼時很實用，但差不多也就這些了。最先的兩個設置屏幕，以及相機界面，這是應用裏僅有的現在還能運行的了。由於客户端太舊了，實際上你如今並不能完成一個搜索。應用裏也沒什麼太多可看的，也就一個會返回搜索結果頁的相機界面而已。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/twitters-2.png" alt="Twitter應用，一個充滿動畫的谷歌和Twitter的合作成果。"></p><p><em>Twitter 應用，一個充滿動畫的谷歌和 Twitter 的合作成果。 [Ron Amadeo 供圖]</em></p><p>Froyo 擁有首個安卓 Twitter 應用，實際上它是谷歌和 Twitter 的合作成果。那時，Twitter 應用是安卓應用陣容裏的大缺憾之一。開發者們更偏愛 iPhone，加上蘋果佔領先機和嚴格的設計要求，App Store 裏可選擇的應用遠比安卓的有優勢。但是谷歌需要一個 Twitter 應用，所以它和 Twitter 合作組建團隊讓第一個版本問世。</p><p>這個應用代表了谷歌的新設計語言，這意味着它有個中間導航頁以及對動畫要求的“技術演示”。Twitter 應用甚至比 Cooliris 相冊用的動畫效果還多——所有東西一直都在動。所有頁面頂部和底部的雲朵以不同速度持續滾動，底部的 Twitter 小鳥拍動它的翅膀並且左右移動它的頭。</p><p>Twitter 應用實際上有點 Action Bar 早期前身的特性，在安卓 3.0 中引入了一條頂部對齊的連續控制條。沿着所有屏幕的頂部有條擁有 Twitter 標誌以及如搜索、刷新和發推這樣的按鈕的藍色橫欄。它和後來的 Action Bar 之間大的區別在於 Twitter / 谷歌這裏的設計的右上角缺少“上一級”按鈕，實際上它在應用裏用了完整的第二個欄位顯示你當前所在位置。在上面的第二張圖裏，你可以看到整條帶有“Tweets”標籤的專用於顯示位置的欄（當然，還有持續滾動的雲朵）。第二個欄的 Twitter 標誌扮演着另一個導航元素，有時候在當前部分顯示額外的下拉區域，有時候顯示整個頂級快捷方式集合。</p><p>2.3 Tweet 流看起來和今天的並沒有什麼不同，除了隱藏的操作按鈕（回覆，轉推等），都在右對齊的箭頭按鈕裏。它們彈出來的是一個聊天氣泡菜單，看起來就像導航彈窗。仿 Action Bar 在發推頁面有重要作用。它安置着 twitter 標誌，剩餘字數統計，以及添加照片、拍照，以及提到聯繫人按鈕。</p><p>Twitter 應用甚至還有一對主屏幕小部件，大號的那個佔據 8 格，提供了發推欄、更新按鈕、一條推文，以及左右箭頭來查看更多的推文。小號的顯示一條推文以及回覆按鈕。點擊大號的小部件的發推欄立即打開了“新推文”主窗口，這讓“更新”按鈕變得沒有價值。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/talkusb.png" alt="Google Talk和新USB對話框。"></p><p><em>Google Talk 和新 USB 對話框。 [Ron Amadeo 供圖]</em></p><p>其他部分，Google Talk（以及沒有截圖的短信應用）從暗色主題變成了淺色主題，這讓它們看起來和現在的更接近現代的應用。USB 存儲界面會在你設備接入電腦的時候從一個簡單的對話框進入全屏界面。這個界面現在有個一個異形安卓機器人 / USB 閃存盤混合體，而不是之前的純文字設計。</p><p>儘管安卓 2.2 在用户互動方式上沒有什麼新特性，但大的 UI 調整會在下兩個版本到來。然而在所有的 UI 工作之前，谷歌希望先改進安卓的核心部分。</p><hr><p><img src="http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg" alt="Ron Amadeo"></p>',25)),n("p",null,[r(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:i(()=>[...o[11]||(o[11]=[t("Ron Amadeo",-1)])]),_:1}),o[13]||(o[13]=t(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。 ",-1)),r(e,{href:"https://twitter.com/RonAmadeo"},{default:i(()=>[...o[12]||(o[12]=[t("@RonAmadeo",-1)])]),_:1})]),o[38]||(o[38]=n("hr",null,null,-1)),n("p",null,[o[15]||(o[15]=t("via: ",-1)),r(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/13/"},{default:i(()=>[...o[14]||(o[14]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/13/",-1)])]),_:1})]),n("p",null,[o[18]||(o[18]=t("譯者：",-1)),r(e,{href:"https://github.com/alim0x"},{default:i(()=>[...o[16]||(o[16]=[t("alim0x",-1)])]),_:1}),o[19]||(o[19]=t(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...o[17]||(o[17]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[22]||(o[22]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[20]||(o[20]=[t("LCTT",-1)])]),_:1}),o[23]||(o[23]=t(" 原創翻譯，",-1)),r(e,{href:"http://linux.cn/"},{default:i(()=>[...o[21]||(o[21]=[t("Linux中國",-1)])]),_:1}),o[24]||(o[24]=t(" 榮譽推出",-1))])])}const b=d(u,[["render",m]]);export{F as __pageData,b as default};
